<div class="headline"><div><h1><?= $id ? 'Editar inscripción' : 'Nueva inscripción' ?></h1><p class="subtitle">Selecciona un evento y un participante.</p></div></div>
            <section class="panel">
                <?php if (!$eventos || !$participantes): ?><div class="alert error">Primero debes registrar al menos un <a href="<?= h(url('eventos')) ?>">evento</a> y un <a href="<?= h(url('participantes')) ?>">participante</a>.</div><?php endif; ?>
                <form method="post" action="index.php"><input type="hidden" name="action" value="save_inscripcion"><input type="hidden" name="id" value="<?= $id ?>"><?= csrf_field() ?>
                <div class="form-grid"><div class="field"><label for="evento_id">Evento *</label><select name="evento_id" id="evento_id" required><option value="">Selecciona un evento</option><?php foreach ($eventos as $e): ?><option value="<?= (int)$e['evento_id'] ?>" <?= (int)$r['evento_id'] === (int)$e['evento_id'] ? 'selected' : '' ?>><?= h($e['nombre'] . ' — ' . $e['fecha']) ?></option><?php endforeach; ?></select></div><div class="field"><label for="participante_id">Participante *</label><select name="participante_id" id="participante_id" required><option value="">Selecciona un participante</option><?php foreach ($participantes as $p): ?><option value="<?= (int)$p['participante_id'] ?>" <?= (int)$r['participante_id'] === (int)$p['participante_id'] ? 'selected' : '' ?>><?= h($p['apellido'] . ' ' . $p['nombre'] . ' — ' . $p['email']) ?></option><?php endforeach; ?></select></div></div>
                <div class="form-actions"><button class="btn" <?= (!$eventos || !$participantes) ? 'disabled' : '' ?>>Guardar inscripción</button><a class="btn btn-light" href="<?= h(url('inscripciones')) ?>">Cancelar</a></div>
                </form>
            </section>
